<?php
require_once __DIR__.'/includes/db.php';$q=trim((string)($_GET['q']??''));$cat=trim((string)($_GET['category']??''));$sql="SELECT p.*,(SELECT image_path FROM screenshots s WHERE s.product_id=p.id ORDER BY s.id LIMIT 1) cover FROM products p WHERE p.status='published'";$a=[];if($q!==''){$sql.=" AND (p.title LIKE ? OR p.description LIKE ?)";$a[]="%$q%";$a[]="%$q%";}if($cat!==''){$sql.=" AND p.category=?";$a[]=$cat;}$sql.=" ORDER BY p.created_at DESC";$st=$pdo->prepare($sql);$st->execute($a);$products=$st->fetchAll();$cats=$pdo->query("SELECT DISTINCT category FROM products WHERE status='published' AND category<>'' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN);$pageTitle='HENDY | Kho ứng dụng & dịch vụ';require __DIR__.'/includes/header.php';?><section class="hero"><div class="eyebrow">HENDY CYBERTECH • DIGITAL SOLUTIONS</div><h1>Công nghệ kết nối.<br><span>Giá trị thật.</span></h1><p>Khám phá kho ứng dụng, công cụ và dịch vụ kỹ thuật số từ HENDY.</p><a class="button primary" href="#catalog">Khám phá ngay →</a><div class="hero-orb orb-one"></div><div class="hero-orb orb-two"></div></section><section id="catalog" class="section-head"><div><div class="eyebrow">HENDY COLLECTION</div><h2>Khám phá dịch vụ</h2><p class="muted">Các sản phẩm và giải pháp đang được cung cấp.</p></div><form class="search-form" method="get"><input name="q" value="<?=e($q)?>" placeholder="Tìm kiếm sản phẩm..."><select name="category"><option value="">Tất cả danh mục</option><?php foreach($cats as $c):?><option value="<?=e($c)?>" <?=$cat===$c?'selected':''?>><?=e($c)?></option><?php endforeach;?></select><button class="button">Tìm</button></form></section><div class="product-grid"><?php foreach($products as $p):?><article class="product-card"><a class="product-cover" href="detail.php?id=<?=(int)$p['id']?>"><?php if($p['cover']):?><img src="<?=e($p['cover'])?>" alt="<?=e($p['title'])?>" loading="lazy"><?php else:?><div class="cover-placeholder">HENDY ✦</div><?php endif;?><span class="category-tag"><?=e($p['category']?:'Dịch vụ')?></span></a><div class="product-info"><h3><a href="detail.php?id=<?=(int)$p['id']?>"><?=e($p['title'])?></a></h3><p><?=e(mb_strimwidth(strip_tags($p['description']),0,125,'…','UTF-8'))?></p><div class="product-bottom"><strong><?=e($p['price']?:'Liên hệ')?></strong><a href="detail.php?id=<?=(int)$p['id']?>">Chi tiết →</a></div></div></article><?php endforeach;?></div><?php if(!$products):?><div class="empty-state"><div>✦</div><h3>Chưa có sản phẩm phù hợp</h3><p>Hãy thử từ khóa hoặc danh mục khác.</p></div><?php endif;?><?php require __DIR__.'/includes/footer.php';?>